def execute_agent_step(action: dict, sandbox, hitl_gate) -> dict:
    act_type = action.get('type', '')
    if not act_type:
        raise ValueError('Action type is required')
    if act_type in SENSITIVE_ACTIONS and not hitl_gate.is_approved(action):
        return {'status': 'AWAITING_HUMAN_APPROVAL', 'action': action}
    return sandbox.dispatch_bounded(action, timeout_sec=10.0)
